export interface CacheOptions {
  ttlMs?: number;
  maxSize?: number;
  strategy?: 'lru' | 'fifo';
}

export class Cache<K, V> {
  private store: Map<K, V> = new Map();
  private timestamps: Map<K, number> = new Map();
  private options: Required<CacheOptions>;

  constructor(options: CacheOptions = {}) {
    this.options = {
      ttlMs: options.ttlMs ?? 60000,
      maxSize: options.maxSize ?? 100,
      strategy: options.strategy ?? 'lru'
    };
  }

  set(key: K, value: V): void {
    if (this.store.size >= this.options.maxSize && !this.store.has(key)) {
      this.evict();
    }
    this.store.set(key, value);
    this.timestamps.set(key, Date.now());
  }

  get(key: K): V | undefined {
    const expired = Date.now() - (this.timestamps.get(key) ?? 0) > this.options.ttlMs;
    if (expired) {
      this.store.delete(key);
      this.timestamps.delete(key);
      return undefined;
    }
    return this.store.get(key);
  }

  private evict(): void {
